import React, { useEffect, useState } from "react";
import Layout from "../components/Layout";
import api from "../services/api";

const Billing = () => {
    const [bills, setBills] = useState([]);

    const [formData, setFormData] = useState({
        patientName: "",
        service: "",
        amount: "",
        paymentStatus: "Paid",
    });

    // ✅ Fetch Bills History (GET /bill)
    const fetchBills = async () => {
        try {
            const res = await api.get("/bill"); // ✅ Correct Endpoint
            setBills(res.data);
        } catch (error) {
            console.log("Error fetching bills:", error);
        }
    };

    useEffect(() => {
        fetchBills();
    }, []);

    // Handle Input Change
    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value,
        });
    };

    // ✅ Submit Bill (POST /bill)
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await api.post("/bill", formData); // ✅ Correct Endpoint

            alert("✅ Bill Generated Successfully");

            // Reset Form
            setFormData({
                patientName: "",
                service: "",
                amount: "",
                paymentStatus: "Paid",
            });

            // Refresh Bills Table
            fetchBills();
        } catch (error) {
            console.log("Error generating bill:", error);
            alert("❌ Failed to Generate Bill");
        }
    };

    return (
        <Layout>
            <div className="container-fluid">

                {/* Page Header */}
                <div className="d-flex justify-content-between align-items-center mb-4">
                    <h2 className="fw-bold text-success">
                        💰 Billing Management
                    </h2>
                </div>

                {/* Add Bill Form */}
                <div className="card shadow-lg border-0 mb-4">
                    <div className="card-header bg-success text-white fw-bold">
                        ➕ Generate New Bill
                    </div>

                    <div className="card-body">
                        <form onSubmit={handleSubmit}>
                            <div className="row g-3">

                                {/* Patient Name */}
                                <div className="col-md-6">
                                    <label className="form-label fw-semibold">
                                        Patient Name
                                    </label>
                                    <input
                                        type="text"
                                        name="patientName"
                                        value={formData.patientName}
                                        onChange={handleChange}
                                        className="form-control"
                                        placeholder="Enter patient name"
                                        required
                                    />
                                </div>

                                {/* Service */}
                                <div className="col-md-6">
                                    <label className="form-label fw-semibold">
                                        Service Type
                                    </label>
                                    <input
                                        type="text"
                                        name="service"
                                        value={formData.service}
                                        onChange={handleChange}
                                        className="form-control"
                                        placeholder="Consultation / Lab Test"
                                        required
                                    />
                                </div>

                                {/* Amount */}
                                <div className="col-md-6">
                                    <label className="form-label fw-semibold">
                                        Amount (₹)
                                    </label>
                                    <input
                                        type="number"
                                        name="amount"
                                        value={formData.amount}
                                        onChange={handleChange}
                                        className="form-control"
                                        placeholder="Enter amount"
                                        required
                                    />
                                </div>

                                {/* Payment Status */}
                                <div className="col-md-6">
                                    <label className="form-label fw-semibold">
                                        Payment Status
                                    </label>
                                    <select
                                        name="paymentStatus"
                                        value={formData.paymentStatus}
                                        onChange={handleChange}
                                        className="form-select"
                                    >
                                        <option value="Paid">Paid</option>
                                        <option value="Pending">Pending</option>
                                    </select>
                                </div>

                                {/* Submit Button */}
                                <div className="col-md-12 text-end">
                                    <button type="submit" className="btn btn-primary px-4">
                                        ✅ Generate Bill
                                    </button>
                                </div>

                            </div>
                        </form>
                    </div>
                </div>

                {/* Bills Table */}
                <div className="card shadow-lg border-0">
                    <div className="card-header bg-dark text-white fw-bold">
                        📋 Billing Records
                    </div>

                    <div className="card-body table-responsive">
                        <table className="table table-bordered table-hover align-middle">
                            <thead className="table-secondary text-center">
                                <tr>
                                    <th>#</th>
                                    <th>Patient</th>
                                    <th>Service</th>
                                    <th>Amount</th>
                                    <th>Status</th>
                                </tr>
                            </thead>

                            <tbody className="text-center">
                                {bills.length > 0 ? (
                                    bills.map((bill, index) => (
                                        <tr key={bill._id || index}>
                                            <td>{index + 1}</td>
                                            <td>{bill.patientName}</td>
                                            <td>{bill.service}</td>
                                            <td className="fw-bold">₹ {bill.amount}</td>

                                            <td>
                                                <span
                                                    className={`badge ${bill.paymentStatus === "Paid"
                                                        ? "bg-success"
                                                        : "bg-warning text-dark"
                                                        }`}
                                                >
                                                    {bill.paymentStatus}
                                                </span>
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="5" className="text-muted text-center">
                                            No billing records found
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

            </div>
        </Layout>
    );
};

export default Billing;
